// Security's review rules for the inventory, as tests, so every pull request to the file runs them.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { parse } from "yaml";

type Agent = { name: string; status: string; owner?: string; data?: string; keys?: string; repos: string[]; jira?: string; unattended?: boolean };
const agents = parse(readFileSync("inventory/agents.yaml", "utf8")) as Agent[];
const planned = agents.filter((a) => a.status === "planned");

test("every agent has an owner and says what data it sees and whether it runs unattended", () => {
  for (const a of agents) assert.ok(a.owner && a.data && typeof a.unattended === "boolean", `${a.name} is missing owner, data or unattended`);
});

test("no agent sees PHI", () => {
  for (const a of agents) assert.match(a.data ?? "", /no PHI/, `${a.name}: data must say no PHI`);
});

test("a planned agent holds no keys in its VM", () => {
  for (const a of planned) assert.equal(a.keys, "none in the VM", `${a.name} has keys: ${a.keys}`);
});

test("a planned agent works in exactly one repo", () => {
  for (const a of planned) assert.equal(a.repos.length, 1, `${a.name} has repos: ${a.repos.join(", ")}`);
});

