// Answer "which agents can touch this?" from the inventory alone. usage: node who.ts <repo or Slack channel>
import { readFileSync } from "node:fs";
import { parse } from "yaml";

type Agent = { name: string; status: string; repos: string[]; slack: string[]; writes: string[]; unattended: boolean };
const agents = parse(readFileSync("inventory/agents.yaml", "utf8")) as Agent[];
const thing = process.argv[2] ?? "";

const hits = agents.filter((a) => [...a.repos, ...a.slack].includes(thing));
for (const a of hits) {
  console.log(`${a.name.padEnd(10)} ${a.status.padEnd(8)} ${a.unattended ? "unattended " : "supervised "} writes: ${a.writes.join(", ")}`);
}
console.log(hits.length ? `${hits.length} agent(s) can touch ${thing}` : `no agent can touch ${thing}`);
EOF
