// rules.test.ts: the new rule. In agents.yaml, cifix gets keys: none in the VM, and bug-fixer gets
// repos: [RhinoHealth/fcp] (a bug in another repo goes to a person) and jira: its own ticket only.
test("an unattended agent writes in Jira only on its own ticket", () => {
  for (const a of planned.filter((a) => a.unattended)) {
    assert.ok(["none", "its own ticket only"].includes(a.jira ?? ""), `${a.name} has jira: ${a.jira}`);
  }
});
